grid = [[1]*11 for _ in range(28)]
marks = [(1,8),(3,4),(3,8),(3,10),(5,2),(5,3),(6,8),(7,6),(8,6),(12,9),(14,1),(14,9),(15,5),(16,2),(16,5),(16,11),(18,1),(21,4),(21,5),(21,10),(22,6),(22,8),(23,2),(24,4),(24,8),(28,6),(28,10)]
for r,c in marks: grid[r-1][c-1]=7
# Fill between every pair of markers sharing a row or column, preserving markers.
for r in range(1,29):
    cs=sorted(c for rr,c in marks if rr==r)
    if cs:
        for c in range(cs[0],cs[-1]+1):
            if grid[r-1][c-1] != 7: grid[r-1][c-1]=3
for c in range(1,12):
    rs=sorted(r for r,cc in marks if cc==c)
